import re, sys
from pathlib import Path
def slug(h): return re.sub(r"[^a-z0-9 -]", "", h.strip().lower()).replace(" ", "-")
bad = []
for f in sys.argv[1:]:
    p = Path(f); text = p.read_text()
    for target in re.findall(r"\]\(([^)\s]+)\)", text):
        if re.match(r"[a-z]+:", target): continue
        path, _, anchor = target.partition("#")
        dest = (p.parent / path) if path else p
        if not dest.exists(): bad.append((f, target, "missing file")); continue
        if anchor and dest.suffix == ".md":
            heads = {slug(h) for h in re.findall(r"^#{1,6} (.+)$", dest.read_text(), re.M)}
            if anchor not in heads: bad.append((f, target, "missing anchor"))
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if line.startswith("|") and i > 0 and not lines[i - 1].startswith("|"):
            width, j = line.count("|"), i
            while j < len(lines) and lines[j].startswith("|"):
                if lines[j].replace("\\|", "").count("|") != width: bad.append((f, f"row {j+1}", "ragged table"))
                j += 1
print("links, anchors and tables:", bad or "all ok")
EOF
